INSERT INTO voice_lessons (id, lesson_order, module, title, title_zh, minutes, goal, steps) VALUES
('v01', 1, '基础', 'Breathe & Ground', '呼吸与稳定', 5, '让声音靠气息撑住，而不是靠喉咙用力。', '[{"type":"learn","title":"Confident voices run on air","body":"When we are nervous, we breathe high in the chest. The voice turns thin and fast. A slow breath into your belly gives the voice something steady to ride on.","tips":["One hand on your belly, one on your chest. Only the belly hand should move.","Breathe out longer than you breathe in."]},{"type":"timer","title":"Belly breathing","instruction":"肩膀放松。鼻子吸气 4 秒，嘴巴慢慢呼气 6 秒。","seconds":60,"pattern":[{"label":"In","sec":4},{"label":"Out","sec":6}]},{"type":"read","title":"One breath, one sentence","instruction":"吸一口气，把整句话在一口气里读完，不赶。","lines":["I take a slow breath, and I let my words come out on the air."],"target":{"wpm":[110,150]},"selfCheck":["整句话读完时我没有喘不过气","声音比平时更稳、更低一点"]},{"type":"speak","title":"Say it calmly","prompt":"Say your name and one thing you did today. Breathe before you start.","seconds":20,"target":{"minSeconds":8}}]'::jsonb),
('v02', 2, '基础', 'Open Your Mouth', '把嘴张开', 5, '很多"听不清"其实是嘴张得不够，不是声音太小。', '[{"type":"learn","title":"Mumbling is a small jaw","body":"Clear speech needs a loose, moving jaw. If your jaw barely moves, vowels get squashed and words blur together even when you are loud enough.","tips":["Pretend you are chewing a big piece of gum while you talk.","Over-do it in practice. In real life it shrinks back to normal."]},{"type":"read","title":"Vowel shapes","instruction":"每个元音都把嘴形做大：下巴放松下落。","lines":["Ah, eh, ee, oh, oo. Ah, eh, ee, oh, oo."],"target":{"wpm":[60,130]},"selfCheck":["我能感觉到下巴在动","对着镜子，嘴形明显在变化"]},{"type":"read","title":"Big mouth sentence","instruction":"夸张地读。录完回放，听每个元音是否饱满。","lines":["How now, brown cow? The loud crowd found the round mountain town."],"target":{"wpm":[110,150]}},{"type":"speak","title":"Describe the room","prompt":"Describe the room you are in. Keep your jaw loose and your mouth open.","seconds":25,"target":{"minSeconds":10}}]'::jsonb),
('v03', 3, '口齿', 'Crisp Consonants', '辅音要清脆', 5, 'P、T、K 这些爆破音是清晰度的"边缘"。', '[{"type":"learn","title":"Consonants are the edges of words","body":"Vowels carry your voice. Consonants carry the meaning. Sharp P, T, K and B, D, G sounds make speech easy to follow without making you louder.","tips":["Feel a small puff of air on your hand for P and T.","Start slow. Speed comes after clarity."]},{"type":"read","title":"Pop and tap","instruction":"先慢读，每个爆破音都\"弹\"出来；再稍微加快一遍。","lines":["Peter Piper picked a peck of pickled peppers.","Top cat! Kick back. Pick it up quick."],"target":{"wpm":[90,160]},"selfCheck":["P / T / K 的开头听起来干净","没有因为加速而糊成一团"]},{"type":"speak","title":"What did you eat?","prompt":"Tell me what you ate today and what it tasted like. Make every first sound crisp.","seconds":25,"target":{"minSeconds":10}}]'::jsonb),
('v04', 4, '口齿', 'Finish Your Words', '把词尾说完', 5, '不再把句尾吞掉、越说越小声。', '[{"type":"learn","title":"The last sound matters","body":"Under pressure we trail off. The end of the word, and the end of the sentence, fades away. Listeners then miss the exact part that carried the point.","tips":["Land the last consonant: \"send\", \"noon\", \"gift\".","Keep your energy up until the final word, then stop. Do not fade out."]},{"type":"read","title":"Strong endings","instruction":"每个词最后的 t / d / k / ft 都落地，句尾音量不要掉。","lines":["I will send the draft at noon.","Let''s meet next Monday, first thing.","It was a great, fast, kind gift."],"target":{"wpm":[100,145]},"selfCheck":["句尾和句首一样响","词尾的 t / d / k 我都听得见"]},{"type":"speak","title":"Weekend plans","prompt":"Tell me your plans for the weekend in three sentences. Finish every last word.","seconds":30,"target":{"minSeconds":12}}]'::jsonb),
('v05', 5, '口齿', 'Tricky Sounds', '易混淆的音', 5, '针对 S / SH、R / L 这类容易含糊的音做集中练习。', '[{"type":"learn","title":"Slow first, then speed up","body":"Tongue twisters are strength training for the mouth. The goal is not speed. Say them slowly and correctly three times, then speed up only while staying clear.","tips":["Smile slightly for S, round your lips for SH.","For R and L, notice where your tongue touches."]},{"type":"read","title":"S and SH","instruction":"先慢后快，各读两遍。","lines":["She sells seashells by the seashore.","Six slippery snails slid slowly seaward."],"target":{"wpm":[80,150]},"selfCheck":["S 和 SH 听得出区别"]},{"type":"read","title":"R and L","instruction":"舌位要到位，别急。","lines":["Red lorry, yellow lorry, red lorry, yellow lorry.","Really leery rural railway."],"target":{"wpm":[80,150]}}]'::jsonb),
('v06', 6, '节奏', 'Slow Down to Sound Clear', '慢一点，反而更清楚', 6, '找到你自己的"清晰语速"区间（约 110–150 词/分钟）。', '[{"type":"learn","title":"Fast is not smart","body":"Nervous speakers speed up to get it over with. A slightly slower pace gives your mouth time to form words and gives listeners time to understand them. It also sounds more sure of itself.","tips":["Your target is roughly 110–150 words per minute.","If you notice rushing, take a breath. That is a free reset."]},{"type":"read","title":"Steady paragraph","instruction":"用\"讲给朋友听\"的速度读，不要念经。","lines":["Every morning I make a cup of tea and sit by the window. I do not check my phone. I just watch the street wake up. It is a small habit, but it helps me start the day calm and clear."],"target":{"wpm":[110,150]}},{"type":"speak","title":"Explain a routine","prompt":"Explain how to make your favourite drink, step by step. Keep a steady pace.","seconds":40,"target":{"wpm":[110,150],"minSeconds":15}}]'::jsonb),
('v07', 7, '节奏', 'The Power Pause', '停顿的力量', 5, '把"嗯、呃"换成安静的停顿。', '[{"type":"learn","title":"Silence is not a mistake","body":"A pause of half a second feels long to you and normal to everyone else. Pauses let you breathe, think, and let your point land. Fillers like \"um\" are often just pauses you were afraid to leave empty.","tips":["Pause at every / mark. Count \"one\" silently.","Close your mouth during the pause. It stops \"um\" sneaking in."]},{"type":"read","title":"Pause on the slash","instruction":"遇到 / 就安静停半拍再继续。","lines":["Good morning everyone. / Today I want to share one idea. / It is simple. / Small steps, / repeated daily, / beat big plans."],"target":{"wpm":[90,140],"pauses":4},"selfCheck":["停顿时我没有说\"嗯\"","停顿让重点更突出"]},{"type":"speak","title":"One idea","prompt":"Share one idea you believe in. Pause between your thoughts instead of filling the gap.","seconds":35,"target":{"pauses":2,"minSeconds":15}}]'::jsonb),
('v08', 8, '音量', 'Fill the Room', '让声音到达后排', 5, '用气息送声，不是用喉咙喊。', '[{"type":"learn","title":"Aim at the far wall","body":"Volume comes from breath support, not throat force. Imagine your voice has to reach a person at the back of the room. Your body adjusts automatically.","tips":["Stand or sit tall. Slumping squeezes your breath.","Louder is not shouting. Think \"projected\", not \"pushed\"."]},{"type":"timer","title":"Hum and open","instruction":"深吸气，用 \"mmm\" 哼 6 秒，然后张嘴变成 \"ah\" 再 6 秒。","seconds":45,"pattern":[{"label":"In","sec":4},{"label":"Hum / Ah","sec":8}]},{"type":"read","title":"Back-of-the-room voice","instruction":"想象对面站着一个 5 米外的人。","lines":["Hello! Can everyone hear me at the back? Wonderful. Let us begin."],"target":{"wpm":[110,150]},"selfCheck":["我没有靠喊，喉咙不紧","回放时声音听起来饱满而不尖"]},{"type":"speak","title":"Welcome a group","prompt":"Welcome an imaginary group of six people to a meeting. Reach the far wall.","seconds":25,"target":{"minSeconds":10}}]'::jsonb),
('v09', 9, '表达', 'Add Melody', '让声音有起伏', 5, '避免平板腔，用音调变化传递情绪。', '[{"type":"learn","title":"Monotone loses people","body":"When pitch stays flat, listeners tune out even when the content is good. Let your voice rise on new or exciting information and fall when you settle a point.","tips":["Smile while you talk. It lifts your pitch naturally.","Mark two or three words per sentence to \"lean on\"."]},{"type":"read","title":"Story voice","instruction":"像给小朋友讲故事一样，夸张起伏。","lines":["You will not believe what happened this morning! I opened the door, and there, on the doorstep, was the biggest, fluffiest cat I have ever seen."],"target":{"wpm":[110,160]},"selfCheck":["回放时我的声音有明显的高低起伏","重要的词比周围更突出"]},{"type":"speak","title":"Good news","prompt":"Tell me about something good that happened recently. Let your voice show that it was good.","seconds":30,"target":{"minSeconds":12},"selfCheck":["我的声音听起来和内容一样开心"]}]'::jsonb),
('v10', 10, '表达', 'Stress the Key Word', '重音放对地方', 5, '重音决定一句话的意思。', '[{"type":"learn","title":"One word changes the meaning","body":"Stress is a spotlight. The word you lean on tells the listener what matters. Same sentence, different stress, different meaning.","tips":["Stress = slightly louder, slightly longer, slightly higher.","Pick one key word per phrase. Stressing everything stresses nothing."]},{"type":"read","title":"Move the spotlight","instruction":"每行把大写的词重读，听出意思的变化。","lines":["I didn''t say HE stole the money.","I didn''t say he STOLE the money.","I didn''t say he stole the MONEY."],"target":{"wpm":[90,150]},"selfCheck":["三句话听起来意思明显不同"]},{"type":"speak","title":"Recommend something","prompt":"Recommend a book, show or place. Lean on the key words that make people want it.","seconds":30,"target":{"minSeconds":12}}]'::jsonb),
('v11', 11, '表达', 'Land the Sentence', '把句子稳稳落地', 5, '陈述句句尾下落，听起来更笃定，而不是像在问问题。', '[{"type":"learn","title":"Statements go down","body":"Ending a statement with a rising tone makes it sound like a question and signals doubt. Let your pitch fall on the last word and stop. A short, firm landing sounds confident.","tips":["Say the sentence, then stay silent for a beat.","Do not add \"right?\" or \"you know?\" unless you really ask."]},{"type":"read","title":"Falling endings","instruction":"每句话音调下落，然后停一拍。","lines":["My name is Alex. / I work in design. / I enjoy hiking on weekends. / It is nice to meet you."],"target":{"wpm":[90,140],"pauses":3},"selfCheck":["每句话的最后一个词音调是往下的","我没有把陈述句说成问句"]},{"type":"speak","title":"Three facts","prompt":"State three facts about yourself. Land each one and pause.","seconds":25,"target":{"pauses":2,"minSeconds":10}}]'::jsonb),
('v12', 12, '应用', 'Your 20-Second Intro', '20 秒自我介绍', 6, '把前面所有技巧用在最常用的开场上。', '[{"type":"learn","title":"Name, role, one human detail","body":"A strong intro is short: who you are, what you do, and one detail people can remember. Use everything so far: breathe first, open your mouth, finish the words, pause, land the sentence.","tips":["Breathe before the first word.","Aim for around 20 seconds."]},{"type":"speak","title":"Take 1","prompt":"Introduce yourself in about 20 seconds: your name, what you do, and one thing people remember about you.","seconds":30,"target":{"wpm":[110,150],"minSeconds":14},"selfCheck":["我先吸了一口气再开口","我说完每个词，句尾没有掉音"]},{"type":"speak","title":"Take 2","prompt":"Do it again. Change just one thing: slower, or louder, or with more pauses.","seconds":30,"target":{"wpm":[110,150],"minSeconds":14}}]'::jsonb),
('v13', 13, '应用', 'Speak Up in a Group', '在人群里开口', 6, '在多人场合让别人听见、而不抢话。', '[{"type":"learn","title":"Enter with energy, leave with calm","body":"The first sentence in a group needs a little more volume and a clear start, because people are still shifting their attention. Open with a short, strong line, then settle into your normal pace.","tips":["First sentence: slightly louder than feels natural.","Short lines get heard more often than long ones."]},{"type":"read","title":"Joining the discussion","instruction":"想象你面对 6 个人，坐在桌子另一头。","lines":["If I may add something here. / I had a similar experience last month. / What helped me was breaking the task into three small steps."],"target":{"wpm":[110,150],"pauses":2},"selfCheck":["第一句够响，没有试探","后面保持了稳定节奏"]},{"type":"speak","title":"Add your view","prompt":"Imagine your team is discussing a new idea. Add your view in about 30 seconds.","seconds":40,"target":{"wpm":[110,150],"minSeconds":15}}]'::jsonb),
('v14', 14, '应用', 'Unscripted Under Pressure', '没有稿子也不慌', 6, '没有准备时，仍然稳住气息、节奏和句尾。', '[{"type":"learn","title":"Structure beats talent","body":"When you are put on the spot, use a tiny structure: point, reason, example. Breathe, say your point in one sentence, and pause. Your voice skills are already built. Now trust them.","tips":["Buy a second with a slow breath, not with \"um\".","Point → Reason → Example → Stop."]},{"type":"speak","title":"Random question 1","prompts":["What is something small that made you happy this week?","What is a skill you would like to learn, and why?","Describe a place where you feel relaxed."],"seconds":45,"target":{"wpm":[110,150],"minSeconds":20},"selfCheck":["我先停一拍、吸气，再回答","我没有用\"嗯/呃\"填满空白"]},{"type":"speak","title":"Random question 2","prompts":["What advice would you give your younger self?","What is a tradition you enjoy?","Tell me about someone who inspired you."],"seconds":45,"target":{"wpm":[110,150],"minSeconds":20}}]'::jsonb)
